<?php
declare(strict_types=1);
namespace App\Interface\Http\Review\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Review\Service\GetMasteryMapService;use App\Application\Review\Service\GetNotebookAnalysisService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class ReviewReadController { public function __construct(private AuthService $auth,private GetMasteryMapService $mastery,private GetNotebookAnalysisService $analysis,private ApiResponseFactory $responses){} public function mastery(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,int $page,int $perPage):ResponseInterface{try{$user=$this->auth->currentUser($access);$result=$this->mastery->execute($user->id,$page,$perPage);return $this->responses->paginated($p,$result->items,(string)$r->getAttribute('request_id'),$result->page,$result->perPage,$result->total);}catch(\InvalidArgumentException){return $this->responses->problem($p,'VALIDATION_FAILED','Paginação inválida.',422,(string)$r->getAttribute('request_id'));}catch(\DomainException|UnavailableUserException){return $this->responses->problem($p,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} public function analysis(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,string $id):ResponseInterface{try{$user=$this->auth->currentUser($access);$result=$this->analysis->execute($id,$user->id);return $result===null?$this->responses->problem($p,'RESOURCE_NOT_FOUND','Análise não encontrada.',404,(string)$r->getAttribute('request_id')):$this->responses->success($p,$result,(string)$r->getAttribute('request_id'));}catch(\DomainException|UnavailableUserException){return $this->responses->problem($p,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} }
